def max_coins(nums):
    balloons = [1] + nums + [1]
    n = len(balloons)
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n):
        for l in range(0, n - length):
            r = l + length
            for k in range(l + 1, r):
                coins = balloons[l] * balloons[k] * balloons[r] + dp[l][k] + dp[k][r]
                dp[l][r] = max(dp[l][r], coins)

    return dp[0][n - 1]

